// PV6 collections and galleries, over the real router, index core, policy engine and SQLite D1. Fixtures are
// generated bytes, never real files.

import { randomBytes } from "node:crypto";
import { FakeDigestStream, World, sha256hex, type User } from "./harness.js";

beforeAll(() => {
  (globalThis as unknown as { crypto: { DigestStream?: unknown } }).crypto.DigestStream = FakeDigestStream;
});
afterAll(() => {
  delete (globalThis as unknown as { crypto: { DigestStream?: unknown } }).crypto.DigestStream;
});

const uuidOf = (p: string) => {
  const h = p.split("_")[1]!;
  return `${h.slice(0, 8)}-${h.slice(8, 12)}-${h.slice(12, 16)}-${h.slice(16, 20)}-${h.slice(20)}`;
};

describe("collections", () => {
  let w: World;
  let A: { id: string; pub: string };
  let owner: User, editor: User, viewer: User, guest: User;
  let base: string;

  beforeEach(async () => {
    w = new World();
    w.now = new Date();
    A = w.newOrg();
    owner = w.newUser("owner");
    editor = w.newUser("editor");
    viewer = w.newUser("viewer");
    guest = w.newUser("guest");
    w.grant(A, owner, "owner");
    w.grant(A, editor, "builder");
    w.grant(A, viewer, "viewer");
    const lib = (await w.call(owner, "POST", `/v1/organizations/${A.pub}/libraries`, { name: "Brand" })).json.data.library;
    base = `/v1/organizations/${A.pub}/libraries/${lib.id}`;
    await w.call(owner, "PUT", `${base}/members/${editor.id}`, { role: "editor" });
    await w.call(owner, "PUT", `${base}/members/${viewer.id}`, { role: "viewer" });
    await w.call(owner, "POST", `${base}/invitations`, { email: guest.email, role: "uploader" });
    await w.call(guest, "POST", "/v1/media/invitations/accept");
  });

  async function upload(name: string, extra: Record<string, unknown> = {}) {
    const bytes = randomBytes(200);
    const s = (await w.call(owner, "POST", `${base}/uploads`, { name, size: bytes.length, sha256: sha256hex(bytes), mime: "application/octet-stream", ...extra })).json.data.session;
    await w.put(owner, `${base}/uploads/${s.id}/parts/1`, bytes);
    const f = (await w.call(owner, "POST", `${base}/uploads/${s.id}/commit`)).json.data.file;
    await w.runPipelines();
    return (await w.call(owner, "GET", `${base}/files/${f.id}`)).json.data.file;
  }
  const items = (col: string, action: "add" | "remove", ids: string[], user = editor) => w.call(user, "POST", `${base}/collections/${col}/items`, { action, ids });

  it("editors make collections and add files in order; everyone who can list sees them; uploaders and viewers can't change them", async () => {
    const [a, b, c] = [await upload("a.png", { mime: "image/png" }), await upload("b.bin"), await upload("c.bin")];
    const made = await w.call(editor, "POST", `${base}/collections`, { name: "Launch", description: "For the launch" });
    expect(made.status).toBe(201);
    const col = made.json.data.collection;
    expect(col).toMatchObject({ name: "Launch", description: "For the launch", publicGallery: false, galleryUrl: null, files: 0 });

    const added = await items(col.id, "add", [c.id, a.id, b.id, a.id, "fil_" + "0".repeat(32)]);
    expect(added.json.data).toMatchObject({ changed: 3, failed: ["fil_" + "0".repeat(32)] });
    expect(added.json.data.collection).toMatchObject({ files: 3, coverFileId: a.id });
    const got = await w.call(viewer, "GET", `${base}/collections/${col.id}`);
    expect(got.json.data.files.map((f: { name: string }) => f.name)).toEqual(["c.bin", "a.png", "b.bin"]);
    expect((await w.call(viewer, "GET", `${base}/collections`)).json.data.collections).toHaveLength(1);

    expect((await w.call(viewer, "POST", `${base}/collections`, { name: "Nope" })).status).toBe(404);
    expect((await items(col.id, "add", [a.id], viewer)).status).toBe(404);
    expect((await w.call(guest, "GET", `${base}/collections`)).status).toBe(404);
    expect((await w.call(editor, "POST", `${base}/collections`, { name: "" })).status).toBe(422);

    // a trashed file drops out of the collection; a purged one leaves it for good
    await w.call(editor, "DELETE", `${base}/files/${b.id}`);
    expect((await w.call(viewer, "GET", `${base}/collections/${col.id}`)).json.data.files.map((f: { name: string }) => f.name)).toEqual(["c.bin", "a.png"]);
    await w.call(editor, "POST", `${base}/files/${b.id}/restore`);
    expect((await w.call(viewer, "GET", `${base}/collections/${col.id}`)).json.data.collection.files).toBe(3);
    await w.call(editor, "DELETE", `${base}/files/${b.id}`);
    await w.call(editor, "DELETE", `${base}/files/${b.id}?permanent=1`);
    const core = [...w.index.cores.values()][0]!;
    expect(core.inCollection(uuidOf(col.id), uuidOf(b.id))).toBe(false);

    expect((await items(col.id, "remove", [c.id])).json.data.changed).toBe(1);
    const renamed = await w.call(editor, "PATCH", `${base}/collections/${col.id}`, { name: "Launch day" });
    expect(renamed.json.data.collection.name).toBe("Launch day");
    expect((await w.call(editor, "DELETE", `${base}/collections/${col.id}`)).status).toBe(200);
    expect((await w.call(viewer, "GET", `${base}/collections/${col.id}`)).status).toBe(404);
    // the files stay
    expect((await w.call(viewer, "GET", `${base}/files/${a.id}`)).status).toBe(200);
  });

  it("a public gallery shows only its public files, and only while public sharing is on", async () => {
    const pub = await upload("pub.png", { mime: "application/octet-stream", visibility: "public" });
    const priv = await upload("priv.bin");
    const col = (await w.call(editor, "POST", `${base}/collections`, { name: "Gallery", publicGallery: true })).json.data.collection;
    expect(col.galleryUrl).toMatch(/^https:\/\/serve\.test\/[^/]+\/brand\/_gallery\/[0-9a-f]{32}$/);
    await items(col.id, "add", [pub.id, priv.id]);
    const core = [...w.index.cores.values()][0]!;
    const g = core.gallery(uuidOf(col.id))!;
    expect(g.files.map((f) => f.name)).toEqual(["pub.png"]);
    // not a gallery: nothing
    const plain = (await w.call(editor, "POST", `${base}/collections`, { name: "Private" })).json.data.collection;
    expect(core.gallery(uuidOf(plain.id))).toBeNull();

    w.env.PUBLIC_SHARING = "off";
    expect((await w.call(editor, "GET", `${base}/collections/${col.id}`)).json.data.collection.galleryUrl).toBeNull();
    expect((await w.call(editor, "POST", `${base}/collections`, { name: "G2", publicGallery: true })).status).toBe(409);
    expect((await w.call(editor, "PATCH", `${base}/collections/${plain.id}`, { publicGallery: true })).status).toBe(409);
  });

  it("a collection share link reaches only files in the collection, and stops reaching one removed from it", async () => {
    const [a, b, outside] = [await upload("a.bin"), await upload("b.bin"), await upload("out.bin")];
    const col = (await w.call(editor, "POST", `${base}/collections`, { name: "For the client" })).json.data.collection;
    await items(col.id, "add", [a.id, b.id]);
    const link = await w.call(editor, "POST", `${base}/share-links`, { target: { kind: "collection", collectionId: col.id } });
    expect(link.status).toBe(201);
    expect(link.json.data.shareLink).toMatchObject({ targetKind: "collection", target: col.id, targetLabel: "For the client" });
    const t = link.json.data.url.split("/_s/")[1];
    const opened = await w.call(null, "POST", "/v1/media/shares/open", { token: t });
    expect(opened.json.data.share).toMatchObject({ kind: "collection", label: "For the client" });
    expect(opened.json.data.files.map((f: { name: string }) => f.name)).toEqual(["a.bin", "b.bin"]);
    const content = async (id: string) => (await w.raw("POST", "/v1/media/shares/content", { token: t, fileId: id })).status;
    expect(await content(a.id)).toBe(200);
    expect(await content(outside.id)).toBe(404);
    await items(col.id, "remove", [a.id]);
    expect(await content(a.id)).toBe(404);
    expect((await w.call(editor, "GET", `${base}/share-links?collection=${col.id}`)).json.data.shareLinks).toHaveLength(1);
  });
});
